- **Add grouping utility function** (above component, exported for testing):
  ```typescript
  export function groupAgentsByRepo(
    agents: LoomAgentStatus[],
    selectedRepos: string[],
  ): { grouped: Map<string, LoomAgentStatus[]>; other: LoomAgentStatus[] } {
    const grouped = new Map<string, LoomAgentStatus[]>();
    const other: LoomAgentStatus[] = [];

    // Initialize groups for each selected repo (preserves order, shows empty groups)
    for (const repo of selectedRepos) {
      grouped.set(repo, []);
    }

    for (const agent of agents) {
      if (agent.repo && grouped.has(agent.repo)) {
        grouped.get(agent.repo)!.push(agent);
      } else {
        other.push(agent);
      }
    }

    return { grouped, other };
  }
  ```

- **Inside the component, add hook call and grouping state:**
