  const [selectedRepos] = useRepoFilter();

  // Track collapsed state for each repo group
  const [collapsedGroups, setCollapsedGroups] = useState<Record<string, boolean>>(() => {
    try {
      const stored = localStorage.getItem("agents-sidebar-repo-groups-collapsed");
      return stored ? JSON.parse(stored) : {};
    } catch {
      return {};
    }
  });

  // Persist collapsed groups
